import unittest,re
from tools.kjv_archive import load_register,read
class RevelationFinalSelfTests(unittest.TestCase):
 def test_divine_self_and_complete_source_end(self):
  prior,_=load_register('0.10-kjv.277');lang,manifest=load_register('0.10-kjv.278')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('revelation-'):c for c in read(lang.folder/'revelation-final-self-cases.json')};self.assertEqual(len(cases),48)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}-{'worship'}&set(r['keys']))
  anchors={'21:1': ['new heaven and new earth', 'first heaven and first earth', 'no more sea'], '21:2': ['i kjv_john_revelation', 'holy city new kjv_jerusalem', 'from god out of heaven', 'as bride for her/husband'], '21:3': ['out of heaven great voice', 'god kjv_tabernacle_presence_revelation with man:pl', 'they his/people', 'god himself with they', 'their/god'], '21:4': ['all tear:pl away kjv_wipe:fu', 'no more death neither sorrow nor cry:ev neither any more pain', 'former thing:pl'], '21:5': ['ipl all thing:pl new make:pr', 'to i write:imp', 'true and faithful'], '21:6': ['it do:psv:perf', 'ipl kjv_alpha_letter_revelation and kjv_omega_letter_revelation beginning and end', 'ipl to he who thirst:pr', 'kjv_without_price_revelation'], '21:7': ['overcome:pr all thing:pl inherit:fu', 'ipl his/god', 'he mypl/son'], '21:8': ['fearful:pl and believe:neg:ag:pl', 'kjv_abomination:adj:pl and murder:ag:pl', 'kjv_fornication do:ag:pl and kjv_sorcerer:pl', 'idol kjv_worship:ag:pl and all lie:ag:pl', 'second death'], '21:9': ['one_num of seven angel:pl', 'seven kjv_vial_wrath_revelation:pl', 'seven last plague:pl', 'i to thee bride kjv_lamb wife show:fu'], '21:10': ['in spirit to great and high mountain', 'that great city holy kjv_jerusalem', 'out of heaven from god'], '21:11': ['god glory', 'like most precious stone', 'like kjv_jasper stone as crystal clear'], '21:12': ['great and high wall', 'twelve gate:pl', 'twelve angel:pl', 'kjv_israel child:pl twelve kjv_tribe:pl'], '21:13': ['east three gate:pl', 'kjv_north three gate:pl', 'kjv_south three gate:pl', 'west three gate:pl'], '21:14': ['twelve kjv_foundation:pl', 'kjv_lamb twelve kjv_apostle:pl'], '21:15': ['city and its/gate:pl and its/wall', 'gold:adj reed'], '21:16': ['kjv_square', 'length as great as breadth', 'twelve+thousand kjv_furlong_source', 'its/length and breadth and height equal'], '21:17': ['twelve+twelve kjv_cubit', 'man measure:ev that be:pr angel measure:ev'], '21:18': ['wall build:ev of kjv_jasper', 'pure gold like clear glass'], '21:19': ['all kind:pl of precious stone:pl', 'first kjv_foundation kjv_jasper second kjv_sapphire third kjv_chalcedony_revelation fourth kjv_emerald'], '21:20': ['five:ord kjv_sardonyx_revelation six:ord kjv_sardius seven:ord kjv_chrysolyte_revelation eight:ord kjv_beryl nine:ord kjv_topaz ten:ord kjv_chrysoprasus_revelation eleven:ord kjv_jacinth_stone_revelation twelve:ord kjv_amethyst'], '21:21': ['twelve gate:pl twelve pearl:pl', 'each separate gate of one_num pearl', 'pure gold as transparent glass'], '21:22': ['no kjv_temple', 'lord god kjv_almighty and kjv_lamb its/kjv_temple'], '21:23': ['sun neither moon', 'god glory to it light give:pa', 'kjv_lamb its/light'], '21:24': ['they who save:psv:pp nation:pl', 'earth king:pl', 'their/glory and honour'], '21:25': ['by day at all shut:psv:neg:fu', 'no night'], '21:26': ['nation:pl glory and honour'], '21:27': ['anything which defile:pr', 'kjv_abomination work:pr or lie make:pr', 'enter:neg:fu', 'kjv_lamb life book'], '22:1': ['pure life water river as crystal clear', 'out of god and kjv_lamb throne'], '22:2': ['street middle', 'river either side life kjv_tree', 'twelve kind:pl of fruit:pl', 'each month her/fruit', 'nation:pl heal:ev'], '22:3': ['no more curse', 'god and kjv_lamb throne', 'his/servant:pl he:a serve:fu'], '22:4': ['his/face', 'his/name in their/forehead:pl'], '22:5': ['no night', 'candle neither sun light', 'lord god to they light', 'forever and forever rule:fu'], '22:6': ['faithful and true', 'holy prophet:pl lord god', 'soon do:psv:must'], '22:7': ['ipl quickly come:pr', 'this book kjv_prophesy:ev say:ev:pl keep:pr'], '22:8': ['i kjv_john_revelation', 'see:pa and hear:pa', 'hear:perf and see:perf', 'kjv_worship:inf down fall:pa'], '22:9': ['thou it do:neg:imp', 'i thy/kjv_fellowservant_revelation', 'thy/brother:pl prophet:pl', 'they who this book say:ev:pl keep:pr', 'god kjv_worship:imp'], '22:10': ['seal:neg:imp', 'time at hand'], '22:11': ['unjust be:pr still unjust be:opt', 'filthy be:pr still filthy be:opt', 'kjv_righteous be:pr still kjv_righteous be:opt', 'holy be:pr still holy be:opt'], '22:12': ['ipl quickly come:pr', 'mypl/reward with ipl', 'each man kjv_according his/work'], '22:13': ['ipl kjv_alpha_letter_revelation and kjv_omega_letter_revelation beginning and end first and last'], '22:14': ['his/command:pl do:pr', 'life kjv_tree right have:may', 'through gate:pl into city enter:may'], '22:15': ['outside dog:pl', 'kjv_sorcerer:pl and kjv_fornication do:ag:pl and murder:ag:pl', 'idol kjv_worship:ag:pl', 'lie love:pr and make:pr'], '22:16': ['ipl kjv_jesus_matthew mypl/angel', 'in church:pl', 'ipl kjv_david root and offspring and bright and morning star'], '22:17': ['spirit and bride come:imp say:pr', 'he who hear:pr come:imp say:opt', 'he who thirst:pr come:opt', 'whoever will:pr life water kjv_without_price_revelation take:opt'], '22:18': ['i to each man', 'if any man to these thing:pl add:fu', 'god to he plague:pl', 'in this book write:psv:pp'], '22:19': ['from this kjv_prophesy:ev book word:pl', 'his/part out of life book and out of holy city and from thing:pl', 'away take:fu'], '22:20': ['surely ipl quickly come:pr', 'amen even so lord kjv_jesus_matthew come:imp'], '22:21': ['ourone/lord kjv_jesus_matthew kjv_christ_title grace', 'with you all be:opt amen']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('ipl his/god be:fu and he mypl/son',cases['21-7']['analysis'])
  self.assertIn('i thy/kjv_fellowservant_revelation',cases['22-9']['analysis'])
  self.assertIn('ipl kjv_jesus_matthew mypl/angel',cases['22-16']['analysis'])
  self.assertIn('his/command:pl do:pr',cases['22-14']['analysis'])
  self.assertIn('out of life book',cases['22-19']['analysis'])
  self.assertTrue(cases['22-21']['analysis'].endswith('with you all be:opt amen .'))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),7)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
